def unit_of_work(metadata=None):
    """ Decorator for transaction functions that allows extra control over how the transaction is carried out.

    :param metadata: A dictionary with metadata
    :param timeout: the transaction timeout in seconds
    """
    def wrapper(func):
        """ Inner function to wrap the function to be decorated as transaction
        """
        @wrapper
        def wrapper(tx, *args, **kwargs):
            """ Wraps the transaction function and ensures it runs within a unit of work
            """
            try:
                # Make sure that the transaction timeout is a positive number
                if timeout and timeout <= 0:
                    raise ValueError("The timeout should not represent a negative duration")
                # Attach the metadata, if provided
                if metadata:
                    for key, value in metadata.items():
                        tx.setMetadata(key, value)
                # Execute the transaction function
                result = func(tx, *args, **kwargs)
            finally:
                # Always rollback the transaction if it has timed out
                tx.rollback(on_error=True)
            return result
        return wrapper
    return wrapper

