def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if color and platform.system() in ["Linux", "Darwin"]:
        fd = os.open(os.devnull, os.O_RDWR)
        os.dup2(fd, 1)
        os.close(fd)
        os.system("stty -a onlcuc")
    parts = []
    for arg in varargs:
        if len(parts) == 0 or len(parts[-1]) + len(arg) + 1 > _max_length:
            parts.append([])
        parts[-1].append(arg)
    processes = []
    for i in range(target_concurrency):
        proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        processes.append(proc)
    for part in parts:
        for proc in processes:
            if proc.poll() == None:
                break
        else:
            proc = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            processes.append(proc)
        input = b" ".join([_to_bytes(item) for item in part])
        proc.stdin.write(input)
        if color:
            proc.stdin.write(b"\033[0m")
        proc.stdin.close()
        stdout, stderr = proc.communicate()
        if proc.returncode:
            raise subprocess.CalledProcessError(proc.returncode, cmd, stdout.decode() + stderr.decode())
    stdout = b" ".join([proc.stdout.read() for proc in processes]).decode()
    stderr = b" ".join([proc.stderr.read() for proc in processes]).decode()
    return proc.returncode, tuple(stdout, stderr)
