def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = {}
        usage = {}
        def call():
            nonlocal usage
            key = func.__name__
            if key in cache:
                if usage[key] + ttl > timer():
                    del cache[key]
                else:
                    return cache[key]
            else:
                cache[key] = func()
                usage[key] = timer()
                if len(cache) > maxsize:
                    oldest = min(usage, key=usage.get)
                    del cache[oldest]
                    del usage[oldest]
        return call
    return wrapper
