    if key is None:
        raise ValueError("Cache key must be specified")
    if lock is None:
        raise ValueError("Lock must be specified")
    if not isinstance(cache, MutableMapping):
        raise TypeError("Cache must be a mutable mapping")
    if not callable(self):
        raise TypeError("Self must be callable")
    cached_func = lru_cache(maxsize=128)(self)
    def wrapper(self, *args, **kwargs):
        with lock:
            if key(*args, **kwargs) in cache:
                return cache[key(*args, **kwargs)]
            else:
                result = cached_func(self, *args, **kwargs)
                cache[key(*args, **kwargs)] = result
                return result
