def _legacy_mergeOrderings(orderings: List[List[Any]]) -> List[Any]:
    """Merge multiple orderings so that within-ordering order is preserved.

    Args:
        orderings (List[List[Any]]): List of orderings to merge.

    Returns:
        List[Any]: Merged ordering.
    """
    if not orderings:
        return []

    ordering = []
    for i in range(len(orderings[0])):
        for j in range(len(orderings)):
            if i < len(orderings[j]) and orderings[j][i] not in ordering:
                ordering.append(orderings[j][i])

    return ordering

