import re

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective regular expression.
        The error contains as message the list of all errors which occurred in the labels.
        Each element of the list is a dictionary with one key-value pair:
        - key: the label key or label value for which an error occurred as string.
        - value: the error message.

        .. code:: python

        # Example:
        labels = {
                "key1": "valid",
                "key2": ["invalid"],
                "$$": "invalid",
                True: True,
                }
        try:
            _validate_labels(labels)
        except ValidationError as err:
            assert err.messages == [
                {"['invalid']": 'expected string or bytes-like object'},
                {'$$': "Label key '$$' does not match the regex [...]"},
                {'True': 'expected string or bytes-like object'},
                {'True': 'expected string or bytes-like object'},
            ]
    """

    error_messages = []

    for key, value in labels.items():
        if not re.match(r"[a-zA-Z0-9_]+", key):
            error_messages.append({"'{}'".format(key): "Label key '{}' does not match the regex [...]".format(key)})
        if not isinstance(value, str):
            error_messages.append({"'{}'".format(value): "expected string or bytes-like object"})

    if error_messages:
        raise ValidationError(error_messages)


