def absorb(args):
    """
    Given an `args` sequence of expressions, return a new list of expressions applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, ast.BitwiseAnd):
            left, right = arg.values
            if isinstance(left, ast.BitwiseOr) and isinstance(right, ast.BitwiseAnd):
                new_args.append(ast.BitwiseAnd(left.value, right.value))
            elif isinstance(right, ast.BitwiseOr) and isinstance(left, ast.BitwiseAnd):
                new_args.append(ast.BitwiseAnd(left.value, right.value))
            elif isinstance(left, ast.BitwiseNot) and isinstance(right, ast.BitwiseOr):
                new_args.append(ast.BitwiseAnd(left.value, right.value))
            elif isinstance(right, ast.BitwiseNot) and isinstance(left, ast.BitwiseOr):
                new_args.append(ast.BitwiseOr(left.value, right.value))
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args


