def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise TypeError("'func' must be a function")
    if not isinstance(timeout, int) and not isinstance(timeout, float):
        raise TypeError("'timeout' must be an integer or a float")
    if extra_env is not None and not isinstance(extra_env, dict):
        raise TypeError("'extra_env' must be a dictionary")

    try:
        func_module = func.__module__
    except AttributeError:
        raise TypeError("'func' does not appear to be a function object")

    command = [sys.executable, "-m", func_module + "." + func.__name__]

