def from_ticks(cls, ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError("ticks is out of bounds: " + str(ticks))
    hour = ticks // 3600000000000
    minute = (ticks - hour * 3600000000000) // 60000000000
    second = (ticks - hour * 3600000000000 - minute * 60000000000) // 1000000000
    microsecond = ticks - hour * 3600000000000 - minute * 60000000000 - second * 1000000000
