import math

def _get_fractional_seconds(ticks):
    return ((ticks % 1000000000) / 1000000000)

def _get_seconds(ticks):
    return math.floor(ticks / 1000000000)

def _get_minutes(ticks):
    return _get_seconds(ticks) // 60

def _get_hours(ticks):
    return _get_minutes(ticks) // 60

def _get_days(ticks):
    return _get_hours(ticks) // 24

def _get_weekdays(ticks):
    return ticks.weekday()

def _get_monthdays(ticks):
    return ticks.day

def _get_months(ticks):
    return ticks.month

def _get_years(ticks):
    return ticks.year

def from_ticks(ticks, tz=None):
    if not ( 0 <= ticks < 86400000000000 ):
        raise ValueError('Ticks out of bounds.')
    fractional_seconds = _get_fractional_seconds(ticks)
    seconds = _get_seconds(ticks)
    minutes = _get_minutes(ticks)
    hours = _get_hours(ticks)
    days = _get_days(ticks)
    weekdays = _get_weekdays(ticks)
    monthdays = _get_monthdays(ticks)
    months = _get_months(ticks)
    years = _get_years(ticks)
    time = tz.localize(datetime.time(hours, minutes, seconds, fractional_seconds))
    return datetime.datetime.combine(datetime.date(years, months, monthdays), time)

