            if line.startswith("#") or line.strip() == "":
                continue

            # Check if the line is a section header
            if line.startswith("---"):
                # Initialize a new dictionary to store the section data
                current_section = {}

                # Set the section header as the key for the new dictionary
                data[line.strip("# - ")] = current_section

            # Check if the line contains a key-value pair
            elif ":" in line:
                # Extract the key and value from the line
                key, value = line.split(":", 1)

                # Add the key-value pair to the current section dictionary
                current_section[key.strip()] = value.strip()

        # Raise an exception if any required fields are missing
        required_fields = ["spec_id", "spec_name", "spec_version", "spec_application"]
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f"{field} is missing in the spec content")

